 1	import java.util.ArrayList;
 2	import java.util.List;
 3	import java.util.Objects;
 4	
 5	public final class BucketSort {
 6	
 7	    private BucketSort() {
 8	    }
 9	
10	    public static void sort(float[] values) {
11	        Objects.requireNonNull(values, "values");
12	
13	        if (values.length == 0) {
14	            return;
15	        }
16	
17	        List<List<Float>> buckets = createBuckets(values.length);
18	        distributeValues(values, buckets);
19	        sortBuckets(buckets);
20	        mergeBuckets(buckets, values);
21	    }
22	
23	    private static List<List<Float>> createBuckets(int bucketCount) {
24	        List<List<Float>> buckets = new ArrayList<>(bucketCount);
25	        for (int i = 0; i < bucketCount; i++) {
26	            buckets.add(new ArrayList<>());
27	        }
28	        return buckets;
29	    }
30	
31	    private static void distributeValues(float[] values, List<List<Float>> buckets) {
32	        int bucketCount = buckets.size();
33	        for (float value : values) {
34	            validateValue(value);
35	            int bucketIndex = (int) (bucketCount * value);
36	            buckets.get(bucketIndex).add(value);
37	        }
38	    }
39	
40	    private static void sortBuckets(List<List<Float>> buckets) {
41	        for (List<Float> bucket : buckets) {
42	            insertionSort(bucket);
43	        }
44	    }
45	
46	    private static void mergeBuckets(List<List<Float>> buckets, float[] values) {
47	        int index = 0;
48	        for (List<Float> bucket : buckets) {
49	            for (float value : bucket) {
50	                values[index++] = value;
51	            }
52	        }
53	    }
54	
55	    private static void insertionSort(List<Float> bucket) {
56	        for (int i = 1; i < bucket.size(); i++) {
57	            float currentValue = bucket.get(i);
58	            int j = i - 1;
59	            while (j >= 0 && bucket.get(j) > currentValue) {
60	                bucket.set(j + 1, bucket.get(j));
61	                j--;
62	            }
63	            bucket.set(j + 1, currentValue);
64	        }
65	    }
66	
67	    private static void validateValue(float value) {
68	        if (value < 0.0f || value >= 1.0f) {
69	            throw new IllegalArgumentException(
70	                "Bucket sort expects values in the range [0.0, 1.0): " + value
71	            );
72	        }
73	    }
74	}

  1	import java.util.Arrays;
