  3	public final class BucketSortTest {
  4	
  5	    private BucketSortTest() {
  6	    }
  7	
  8	    public static void main(String[] args) {
  9	        sortsValuesInPlace();
 10	        returnsSortedCopyWithoutMutatingInput();
 11	        rejectsOutOfRangeValues();
 12	        rejectsNullInput();
 13	        handlesEmptyInput();
 14	    }
 15	
 16	    private static void sortsValuesInPlace() {
 17	        float[] values = {0.42f, 0.32f, 0.23f, 0.52f, 0.25f, 0.47f};
 18	        BucketSort.sort(values);
 19	
 20	        assertArrayEquals(
 21	            new float[]{0.23f, 0.25f, 0.32f, 0.42f, 0.47f, 0.52f},
 22	            values,
 23	            "sort should order values in place"
 24	        );
 25	    }
 26	
 27	    private static void returnsSortedCopyWithoutMutatingInput() {
 28	        float[] original = {0.78f, 0.17f, 0.39f};
 29	        float[] copy = BucketSort.sortedCopy(original);
 30	
 31	        assertArrayEquals(
 32	            new float[]{0.78f, 0.17f, 0.39f},
 33	            original,
 34	            "sortedCopy should not mutate the source array"
 35	        );
 36	        assertArrayEquals(
 37	            new float[]{0.17f, 0.39f, 0.78f},
 38	            copy,
 39	            "sortedCopy should return sorted data"
 40	        );
 41	    }
 42	
 43	    private static void rejectsOutOfRangeValues() {
 44	        assertThrows(
 45	            IllegalArgumentException.class,
 46	            () -> BucketSort.sort(new float[]{0.5f, 1.0f}),
 47	            "sort should reject values outside [0.0, 1.0)"
 48	        );
 49	    }
 50	
 51	    private static void rejectsNullInput() {
 52	        assertThrows(
 53	            NullPointerException.class,
 54	            () -> BucketSort.sort(null),
 55	            "sort should reject null input"
 56	        );
 57	    }
 58	
 59	    private static void handlesEmptyInput() {
 60	        float[] values = {};
 61	        BucketSort.sort(values);
 62	        assertArrayEquals(new float[]{}, values, "sort should leave empty input unchanged");
 63	    }
 64	
 65	    private static void assertArrayEquals(float[] expected, float[] actual, String message) {
 66	        if (!Arrays.equals(expected, actual)) {
 67	            throw new AssertionError(
 68	                message
 69	                    + ". Expected "
 70	                    + Arrays.toString(expected)
 71	                    + " but was "
 72	                    + Arrays.toString(actual)
 73	            );
 74	        }
 75	    }
 76	
 77	    private static void assertThrows(
 78	        Class<? extends Throwable> expectedType,
 79	        ThrowingRunnable runnable,
 80	        String message
 81	    ) {
 82	        try {
 83	            runnable.run();
 84	        } catch (Throwable error) {
 85	            if (expectedType.isInstance(error)) {
 86	                return;
 87	            }
 88	            throw new AssertionError(
 89	                message + ". Expected " + expectedType.getSimpleName() + " but caught " + error,
 90	                error
 91	            );
 92	        }
 93	
 94	        throw new AssertionError(
 95	            message + ". Expected " + expectedType.getSimpleName() + " but nothing was thrown"
 96	        );
 97	    }
 98	
 99	    @FunctionalInterface
100	    private interface ThrowingRunnable {
101	        void run();
102	    }
103	}
